const page = figma.currentPage;
const rev = await figma.getNodeByIdAsync("6:2");
const stamp = await figma.getNodeByIdAsync("6:15");
const walk = (n, d=0) => [{d, id:n.id, name:n.name, type:n.type, x:n.x, y:n.y, w:n.width, h:n.height, ...( 'characters' in n ? {chars:n.characters} : {})}, ...('children' in n ? n.children.flatMap(c=>walk(c,d+1)) : [])];
return {
  pageChildren: page.children.map(c => ({id:c.id,name:c.name,type:c.type,x:c.x,y:c.y,w:c.width,h:c.height})),
  rev: walk(rev),
  revLayout: {layoutMode: rev.layoutMode, padding:[rev.paddingTop,rev.paddingRight,rev.paddingBottom,rev.paddingLeft], itemSpacing: rev.itemSpacing, cornerRadius: rev.cornerRadius, clips: rev.clipsContent},
  stamp: stamp ? {...walk(stamp)[0], parent: stamp.parent.id, parentName: stamp.parent.name, children: 'children' in stamp ? stamp.children.map(c=>({id:c.id,name:c.name,type:c.type})) : null} : null
};

const rev = await figma.getNodeByIdAsync("6:2");
const stamp = await figma.getNodeByIdAsync("6:15");
if (rev.name !== "Garden-agent revision" || stamp.name !== "garden-stamp") throw new Error("unexpected nodes");
rev.appendChild(stamp);
stamp.layoutPositioning = 'ABSOLUTE';
stamp.rescale(0.6);
stamp.name = "Garden stamp (uploaded garden-stamp.svg)";
stamp.x = rev.width - 56 - stamp.width;
stamp.y = rev.height - 56 - stamp.height;
stamp.constraints = {horizontal:'MAX', vertical:'MAX'};
const details = rev.findOne(n => n.name === "Event details");
const copy = rev.findOne(n => n.name === "Event copy");
return {
  mutatedNodeIds:[stamp.id, rev.id],
  stamp:{id:stamp.id, x:stamp.x, y:stamp.y, w:stamp.width, h:stamp.height, parent:stamp.parent.id},
  copyBounds:{x:copy.x,y:copy.y,right:copy.x+copy.width,bottom:copy.y+copy.height},
  eventText: details.characters,
  revChildren: rev.children.map(c=>({id:c.id,name:c.name}))
};
